export function normalizePlate(raw: string): string {
  return raw.replace(/[\s-]/g, '');
}

export interface Dispute {
  id: string;
  sessionId: string;
  reason: 'wrong-plate' | 'double-charge' | 'wrong-class' | 'other';
  status: DisputeStatus;
  openedAt: number;
  resolvedAt?: number;
}

async process(raw: GantryReading): Promise<TollSession | undefined> {
  const r = this.deduper.accept({ ...raw, plate: { ...raw.plate, text: normalizePlate(raw.plate.text) } });
  if (!r) return undefined;
  if (!isTrusted(r)) {
    this.manualReview.push(r);
    return undefined;
  }
  const session = new TollSession(nextId('ses'), r.plate, this.ledger, this.flags);
  this.store.put(session);
  const amount = this.pricing.quote(r, this.plazaId);
  session.close(amount);
  if (session.state === 'closed') await this.notifier.send(r.plate.text, chargeMessage(r.plate.text, amount, this.plazaId));
  return session;
}

it('charges and notifies a trusted reading', async () => {
  const { p, ledger, notifier } = make();
  const s = await p.process({ gantryId: 'g', laneId: 1, plate: { text: 'ka 01 ab 1234', region: 'KA' }, confidence: 0.97, at: Date.UTC(2026, 0, 1, 3), vehicleClass: 'car' });
  expect(s?.state).toBe('closed');
  expect(ledger.total()).toBe(9500);
  expect(notifier.sent[0]?.message).toContain('₹95.00');
});

it('sends low-confidence reads to manual review', async () => {
  const { p } = make();
  expect(await p.process({ gantryId: 'g', laneId: 1, plate: { text: 'KA01AB1234', region: 'KA' }, confidence: 0.5, at: 0, vehicleClass: 'car' })).toBeUndefined();
  expect(p.manualReview).toHaveLength(1);
});
